import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over' | 'done';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = {
  active: { label: 'В работе', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышен лимит', tone: 'danger' },
  done: { label: 'Завершён', tone: 'info' },
};

const PROJECTS: Project[] = [
  { id: '1', name: 'Атлас платежей', quotaPercent: 42, status: 'active' },
  { id: '2', name: 'Портал самообслуживания', quotaPercent: 88, status: 'warning' },
  { id: '3', name: 'Миграция склада', quotaPercent: 104, status: 'over' },
  { id: '4', name: 'Дашборд аналитики', quotaPercent: 100, status: 'done' },
  { id: '5', name: 'Мобильный чекаут', quotaPercent: 15, status: 'active' },
  { id: '6', name: 'Интеграция CRM', quotaPercent: 96, status: 'warning' },
  { id: '7', name: 'Биллинг v2', quotaPercent: 118, status: 'over' },
  { id: '8', name: 'Каталог продуктов', quotaPercent: 100, status: 'done' },
  { id: '9', name: 'Служба уведомлений', quotaPercent: 30, status: 'active' },
  { id: '10', name: 'Оптимизация поиска', quotaPercent: 91, status: 'warning' },
  { id: '11', name: 'Резервное копирование', quotaPercent: 130, status: 'over' },
  { id: '12', name: 'Архив документов', quotaPercent: 100, status: 'done' },
];

const STATUS_ORDER: ProjectStatus[] = ['active', 'warning', 'over', 'done'];
const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(
    () =>
      activeStatuses.length === 0
        ? PROJECTS
        : PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '640px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_ORDER.map((status) => {
          const isActive = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '16px',
                  padding: '12px 16px',
                  background: 'var(--jx-surface)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <span style={{ flex: 1, minWidth: 0 }}>{project.name}</span>
                <JxProgressCircle value={Math.min(project.quotaPercent, 100)} showValue />
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
          )}
        </>
      )}
    </div>
  );
}

